<form class="form-grid" method="post" action="<?= $workPath ?>/views"><?= csrf_field() ?><?php $savedFilters=$viewEditing?json_decode($viewEditing['filters'],true,32,JSON_THROW_ON_ERROR):[];if($viewEditing): ?><input type="hidden" name="view_id" value="<?= e($viewEditing['id']) ?>"><?php endif; ?><label>Name<input name="name" value="<?= e($viewEditing['name']??'') ?>" maxlength="160" required></label><label>Layout<select name="layout"><?php foreach(WorkService::LAYOUTS as $value=>$label): ?><option value="<?= $value ?>" <?= ($viewEditing['layout']??'list')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Search<input name="filters[q]" value="<?= e($savedFilters['q']??'') ?>" maxlength="200"></label><label>Scope<select name="filters[scope]"><?php foreach(['active'=>'Active work','mine'=>'My work','overdue'=>'Overdue','intake'=>'Intake','archived'=>'Archived'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($savedFilters['scope']??'active')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>State<select name="filters[state]"><option value="">All states</option><?php foreach($states as $state): ?><option value="<?= e($state['id']) ?>" <?= ($savedFilters['state']??'')==$state['id']?'selected':'' ?>><?= e($state['name']) ?></option><?php endforeach; ?></select></label><label>Priority<select name="filters[priority]"><option value="">All priorities</option><?php foreach(WorkService::PRIORITIES as $key=>$label): ?><option value="<?= $key ?>" <?= ($savedFilters['priority']??'')===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Type<select name="filters[issue_type]"><option value="">All types</option><?php foreach(WorkService::TYPES as $value=>$label): ?><option value="<?= $value ?>" <?= ($savedFilters['issue_type']??'')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Release<select name="filters[release]"><option value="">All releases</option><?php foreach($releases as $release): ?><option value="<?= e($release['id']) ?>" <?= ($savedFilters['release']??'')==$release['id']?'selected':'' ?>><?= e($release['name']) ?></option><?php endforeach; ?></select></label><label>Assignee<select name="filters[assignee]"><option value="">All people</option><?php foreach($people as $person): ?><option value="<?= e($person['id']) ?>" <?= ($savedFilters['assignee']??'')==$person['id']?'selected':'' ?>><?= e($person['name']) ?></option><?php endforeach; ?></select></label><label>Cycle<select name="filters[cycle]"><option value="">All cycles</option><?php foreach($cycles as $cycle): ?><option value="<?= e($cycle['id']) ?>" <?= ($savedFilters['cycle']??'')==$cycle['id']?'selected':'' ?>><?= e($cycle['name']) ?></option><?php endforeach; ?></select></label><label>Module<select name="filters[module]"><option value="">All modules</option><?php foreach($modules as $module): ?><option value="<?= e($module['id']) ?>" <?= ($savedFilters['module']??'')==$module['id']?'selected':'' ?>><?= e($module['name']) ?></option><?php endforeach; ?></select></label><label>Label<select name="filters[label]"><option value="">All labels</option><?php foreach($labels as $label): ?><option value="<?= e($label['id']) ?>" <?= ($savedFilters['label']??'')==$label['id']?'selected':'' ?>><?= e($label['name']) ?></option><?php endforeach; ?></select></label><div class="full"><button>Save view</button></div></form>